<parameter name="content">import { Component, type ErrorInfo, type ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("[ErrorBoundary]", error.message, {
      stack: error.stack,
      componentStack: info.componentStack,
    });
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    if (fallback) return fallback(error, this.reset);

    return (
      <div role="alert" style={styles.container}>
        <h2 style={styles.title}>Something went wrong</h2>
        <pre style={styles.message}>{error.message}</pre>
        <button onClick={this.reset} style={styles.button}>
          Retry
        </button>
      </div>
    );
  }
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    padding: "2rem",
    borderRadius: "8px",
    border: "1px solid #f87171",
    background: "#fef2f2",
    color: "#991b1b",
    fontFamily: "sans-serif",
    maxWidth: "480px",
    margin: "2rem auto",
  },
  title: { margin: "0 0 0.5rem", fontSize: "1.125rem" },
  message: {
    fontSize: "0.875rem",
    whiteSpace: "pre-wrap",
    wordBreak: "break-word",
    margin: "0 0 1rem",
  },
  button: {
    padding: "0.5rem 1rem",
    borderRadius: "4px",
    border: "none",
    background: "#dc2626",
    color: "#fff",
    cursor: "pointer",
    fontSize: "0.875rem",
  },
};
